from __future__ import annotations

import base64
import struct
import sys
from pathlib import Path

ICON_PNG_BASE64 = ""


def png_bytes() -> bytes:
    return base64.b64decode(ICON_PNG_BASE64)


def write_icon_files(directory: Path) -> None:
    directory.mkdir(parents=True, exist_ok=True)
    png = png_bytes()
    (directory / "app_icon.png").write_bytes(png)
    header_size = 22
    ico = struct.pack("<HHH", 0, 1, 1)
    ico += struct.pack("<BBBBHHII", 0, 0, 0, 0, 1, 32, len(png), header_size)
    (directory / "app_icon.ico").write_bytes(ico + png)


def main() -> None:
    destination = Path(sys.argv[1]) if len(sys.argv) > 1 else Path("assets")
    write_icon_files(destination)


if __name__ == "__main__":
    main()
